```ts
@Component({ selector: 'app-user', template: '' })
export class UserComponent implements OnInit {
  userId = input.required<string>();
  private readonly http = inject(HttpClient); // inject работает только здесь

  constructor() {
    this.userId(); // ошибка: вход ещё не установлен
  }

  ngOnInit() {
