примитивов ключом может быть само значение — `track item`.

```ts
@Directive({ selector: '[appRepeat]' })
export class RepeatDirective<T> {
  items = input.required<T[]>({ alias: 'appRepeatOf' });

  static ngTemplateContextGuard<T>(
    dir: RepeatDirective<T>,
    ctx: unknown,
  ): ctx is { $implicit: T; index: number } {
    return true;
  }
}
```

