Подписка живёт по контексту внедрения, поэтому вызывать `toSignal` нужно в поле
класса или в конструкторе — иначе понадобится явный `injector`. Ошибки потока
пробрасываются при чтении сигнала.

```ts
@Component({ selector: 'app-list', template: '' })
export class ListComponent {
  items = input.required<Item[]>();

  // выбор сбрасывается при смене списка, но пользователь может менять его сам
  selected = linkedSignal(() => this.items()[0]);

  // расширенная форма: доступно предыдущее значение
  selectedKeepIfPossible = linkedSignal<Item[], Item | undefined>({
    source: this.items,
    computation: (items, previous) =>
      items.find((i) => i.id === previous?.value?.id) ?? items[0],
  });

  select(item: Item) {
    this.selected.set(item); // computed так не умеет
  }
}
```

